local WinchMaker = {}
local PRODUCTS = {
    simple_wood_winch = { name = "Preprost lesen vitel", woodCost = 4, ironCost = 2, ropeCost = 2, time = 5, cost = 150, science = 22, happiness = 1, description = "Preprost lesen vitel za dviganje." },
    iron_reinforced_winch = { name = "Železnookrepljen vitel", woodCost = 3, ironCost = 3, ropeCost = 2, time = 8, cost = 380, science = 35, happiness = 2, prestige = 2, description = "Železnookrepljen vitel za trgovce." },
    silver_gear_winch = { name = "Srebrnazobčani vitel", woodCost = 3, ironCost = 2, silverCost = 1, ropeCost = 2, time = 11, cost = 880, science = 50, happiness = 2, prestige = 6, description = "Srebrnazobčani vitel za plemiče." },
    gold_trimmed_winch = { name = "Zlatookrasni vitel", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, ropeCost = 2, time = 15, cost = 2000, science = 65, happiness = 3, prestige = 14, description = "Zlatookrasni vitel za visoke plemiče." },
    jewel_set_winch = { name = "Draguljasta vitel", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, ropeCost = 2, jewelCost = 1, time = 19, cost = 4400, science = 80, happiness = 5, prestige = 27, description = "Vitel z draguljem za visoko plemstvo." },
    royal_grand_winch = { name = "Kraljevski veliki vitel", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, ropeCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 9500, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski vitel z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    winch_workshop = { name = "Vitelska delavnica", cost = { gold = 280, wood = 160, stone = 120, iron = 6, rope = 6 }, upkeep = 6, qualityBonus = 5 },
    machinery_loft = { name = "Strojna podstrešje", cost = { gold = 1000, wood = 320, stone = 280, silver = 6, gold = 4 }, upkeep = 23, qualityBonus = 18 },
    master_engineer_atelier = { name = "Mojstrski inženirski atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_engineering_palace = { name = "Kraljevska inženirska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
WinchMaker.woodStock = 20; WinchMaker.ironStock = 16; WinchMaker.ropeStock = 12; WinchMaker.silverStock = 6; WinchMaker.goldStock = 6; WinchMaker.jewelStock = 4; WinchMaker.pearlStock = 4
WinchMaker.productStock = {}; WinchMaker.buildings = {}; WinchMaker.maker = nil; WinchMaker.activeMaking = {}; WinchMaker.totalProducts = 0; WinchMaker.dayTimer = 0
function WinchMaker.init() WinchMaker.woodStock=20; WinchMaker.ironStock=16; WinchMaker.ropeStock=12; WinchMaker.silverStock=6; WinchMaker.goldStock=6; WinchMaker.jewelStock=4; WinchMaker.pearlStock=4; WinchMaker.productStock={}; WinchMaker.buildings={}; WinchMaker.maker=nil; WinchMaker.activeMaking={}; WinchMaker.totalProducts=0; WinchMaker.dayTimer=0; print("[WinchMaker] Royal Winch Maker System initialized (6 products, 4 buildings)") end
function WinchMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WinchMaker.maker={name=n or ("Vitelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitelar najet: %s (spretnost: %d)",WinchMaker.maker.name,s),"success") end; return true end
function WinchMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WinchMaker.build(id) local ok,e=WinchMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WinchMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WinchMaker.getQualityBonus() local b=0; for _,bd in ipairs(WinchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WinchMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WinchMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and WinchMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.ropeCost and WinchMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and WinchMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WinchMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WinchMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WinchMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WinchMaker.buildings==0 then return false,"Potrebna vitelska delavnica" end; if not WinchMaker.maker then return false,"Potreben vitelar" end; return true end
function WinchMaker.make(pt,qty) qty=qty or 1; local ok,e=WinchMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WinchMaker.woodStock=WinchMaker.woodStock-d.woodCost*qty end; if d.ironCost then WinchMaker.ironStock=WinchMaker.ironStock-d.ironCost*qty end; if d.ropeCost then WinchMaker.ropeStock=WinchMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then WinchMaker.silverStock=WinchMaker.silverStock-d.silverCost*qty end; if d.goldCost then WinchMaker.goldStock=WinchMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WinchMaker.jewelStock=WinchMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WinchMaker.pearlStock=WinchMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WinchMaker.maker then t=math.max(1,t-math.floor(WinchMaker.maker.skill/12)) end; table.insert(WinchMaker.activeMaking,{id="winch_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WinchMaker.completeMaking(m) local q=1.0+(WinchMaker.getQualityBonus()/100); if WinchMaker.maker then q=q+(WinchMaker.maker.skill/140) end; q=math.min(2.5,q); WinchMaker.productStock[m.productType]=(WinchMaker.productStock[m.productType] or 0)+m.quantity; WinchMaker.totalProducts=WinchMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WinchMaker.maker then WinchMaker.maker.itemsMade=WinchMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WinchMaker.maker.skill=math.min(100,WinchMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitel izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"winch.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function WinchMaker.update(dt) if not _G.state then return end; WinchMaker.dayTimer=WinchMaker.dayTimer+dt; if WinchMaker.dayTimer>=30 then WinchMaker.dayTimer=0; for i=#WinchMaker.activeMaking,1,-1 do local m=WinchMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WinchMaker.completeMaking(m); table.remove(WinchMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WinchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WinchMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WinchMaker.getStats() return {woodStock=WinchMaker.woodStock,ironStock=WinchMaker.ironStock,ropeStock=WinchMaker.ropeStock,silverStock=WinchMaker.silverStock,goldStock=WinchMaker.goldStock,jewelStock=WinchMaker.jewelStock,pearlStock=WinchMaker.pearlStock,productStock=WinchMaker.productStock,numBuildings=#WinchMaker.buildings,hasMaker=WinchMaker.maker~=nil,makerName=WinchMaker.maker and WinchMaker.maker.name or "—",makerSkill=WinchMaker.maker and WinchMaker.maker.skill or 0,activeMaking=#WinchMaker.activeMaking,totalProducts=WinchMaker.totalProducts} end
return WinchMaker
